  def test_valid_email(): assert is_valid_email("user@example.com")
  def test_invalid_email(): assert not is_valid_email("notanemail")
  def test_extract_domain(): assert extract_domain("user@example.com") == "example.com"
  def test_valid_phone(): assert is_valid_phone("+1 555-1234")
  def test_normalize_phone(): assert normalize_phone("+1 (555) 123-4567") == "+15551234567"
  def test_valid_url(): assert is_valid_url("https://example.com/path")
  def test_invalid_url(): assert not is_valid_url("not a url")
  def test_extract_scheme(): assert extract_scheme("https://example.com") == "https"
  def test_valid_iso_date(): assert is_valid_iso_date("2024-01-15")
  def test_invalid_iso_date(): assert not is_valid_iso_date("01/15/2024")
